{
  "name": "@freely01/opencode-notify",
  "version": "1.0.0",
  "description": "opencode 通知插件 - 监听会话事件并通过多渠道推送通知",
  "type": "module",
  "main": "index.ts",
  "exports": {
    ".": "./index.ts",
    "./cli": "./cli.ts",
    "./tui": "./tui.ts"
  },
  "bin": {
    "opencode-notify": "cli.ts"
  },
  "files": [
    "*.ts",
    "control/",
    "senders/",
    "scripts/linux-marquee.py",
    "!scripts/*.ts",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "notification",
    "plugin",
    "notify"
  ],
  "author": "luyanfeng",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/luyanfeng/opencode-notify.git"
  },
  "bugs": {
    "url": "https://github.com/luyanfeng/opencode-notify/issues"
  },
  "homepage": "https://github.com/luyanfeng/opencode-notify#readme",
  "publishConfig": {
    "access": "public"
  },
  "devDependencies": {
    "@types/js-yaml": "^4.0.9",
    "@types/node": "^25.9.1",
    "typescript": "^6.0.3"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.18",
    "js-yaml": "^4.1.1"
  }
}
